import torch
from torch.utils.cpp_extension import load_inline

# --------------------------------------------------------------------
# CUDA kernel implementing a plain FP16 1‑D convolution (stride=1,
# padding=0, dilation=1, groups=1, no bias).  Accumulation is done in
# FP32 for numerical stability.
# --------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

__global__ void conv1d_fp16_kernel(const __half* __restrict__ input,
                                   const __half* __restrict__ weight,
                                   __half* __restrict__ output,
                                   int N, int C_in, int C_out,
                                   int L_in, int K, int L_out) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C_out * L_out;
    if (idx >= total) return;

    int n   = idx / (C_out * L_out);
    int rem = idx % (C_out * L_out);
    int co  = rem / L_out;
    int lo  = rem % L_out;           // output position along length

    float acc = 0.0f;

    // loop over input channels and kernel elements
    for (int ci = 0; ci < C_in; ++ci) {
        const __half* inp_ptr = input + ((n * C_in + ci) * L_in);
        const __half* wgt_ptr = weight + ((co * C_in + ci) * K);
        for (int ki = 0; ki < K; ++ki) {
            int li = lo + ki;        // input index (no padding, stride=1)
            float a = __half2float(inp_ptr[li]);
            float b = __half2float(wgt_ptr[ki]);
            acc += a * b;
        }
    }

    output[idx] = __float2half(acc);
}

torch::Tensor conv1d_fp16(torch::Tensor input, torch::Tensor weight) {
    TORCH_CHECK(input.is_cuda(),    "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(),   "weight must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf,  "input must be half precision");
    TORCH_CHECK(weight.dtype() == torch::kHalf, "weight must be half precision");

    int N     = input.size(0);
    int C_in  = input.size(1);
    int L_in  = input.size(2);
    int C_out = weight.size(0);
    int K     = weight.size(2);
    int L_out = L_in - K + 1;                 // stride=1, padding=0, dilation=1

    auto output = torch::empty({N, C_out, L_out}, input.options());

    const int threads = 256;
    const int blocks  = (N * C_out * L_out + threads - 1) / threads;

    conv1d_fp16_kernel<<<blocks, threads, 0,
                         at::cuda::getCurrentCUDAStream()>>>(
        reinterpret_cast<const __half*>(input.data_ptr()),
        reinterpret_cast<const __half*>(weight.data_ptr()),
        reinterpret_cast<__half*>(output.data_ptr()),
        N, C_in, C_out, L_in, K, L_out
    );

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv1d_fp16", &conv1d_fp16, "FP16 1D convolution (CUDA)");
}
'''

# Compile the inline extension
conv1d_ext = load_inline(name='conv1d_fp16_ext',
                         cpp_sources='',
                         cuda_sources=cuda_source,
                         functions=['conv1d_fp16'],
                         verbose=False)

# --------------------------------------------------------------------
# PyTorch model that uses the custom kernel.
# --------------------------------------------------------------------
class ModelNew(torch.nn.Module):
    """
    Custom 1‑D convolution using the hand‑written CUDA kernel.
    Only the default configuration (stride=1, padding=0, dilation=1,
    groups=1, bias=False) is supported.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 groups: int = 1,
                 bias: bool = False):
        super().__init__()
        assert stride == 1 and padding == 0 and dilation == 1 and groups == 1 and not bias, \
               "ModelNew only implements the default conv1d configuration."
        self.weight = torch.nn.Parameter(
            torch.randn(out_channels,
                        in_channels,
                        kernel_size,
                        dtype=torch.float16,
                        device='cuda')
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        x: (batch_size, in_channels, length)  – must be float16 CUDA tensor
        Returns: (batch_size, out_channels, length_out) float16 CUDA tensor
        """
        return conv1d_ext.conv1d_fp16(x, self.weight)

# --------------------------------------------------------------------
# Simple sanity test (mirrors the reference test harness)
# --------------------------------------------------------------------
if __name__ == "__main__":
    batch_size = 32
    in_channels = 64
    out_channels = 128
    kernel_size = 3
    length = 131072

    model = ModelNew(in_channels, out_channels, kernel_size).cuda()
    x = torch.randn(batch_size, in_channels, length,
                    dtype=torch.float16, device='cuda')
    y = model(x)
    print("Output shape:", y.shape)   # Expected: (32, 128, 131070)
